import React, { useState, useEffect } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import { Link, useNavigate } from "react-router-dom"; // Importando useNavigate
import AdmEditCurso from "./admeditcurso";

const AdmListCurso = () => {
  const [cursos, setCursos] = useState([]); // Estado para armazenar os cursos
  const [filtro, setFiltro] = useState(""); // Filtro para nome do curso
  const [novoCurso, setNovoCurso] = useState(""); // Nome do novo curso a ser adicionado
  const navigate = useNavigate(); // Hook para navegação

  // Função para buscar os cursos no backend
  const fetchCursos = async () => {
    try {
      const resposta = await fetch("http://localhost:5000/cursos");
      if (resposta.ok) {
        const dados = await resposta.json();
        setCursos(dados);
      } else {
        console.error("Erro ao buscar cursos");
      }
    } catch (error) {
      console.error("Erro na requisição:", error);
    }
  };

  // Buscar cursos assim que o componente for montado
  useEffect(() => {
    fetchCursos();
  }, []);

  // Filtra os cursos com base no nome
  const cursosFiltrados = cursos.filter((curso) =>
    curso.nome.toLowerCase().includes(filtro.toLowerCase())
  );

  // Adicionar novo curso no backend e atualizar a lista
  const adicionarCurso = async () => {
    if (!novoCurso.trim()) return;

    const cursoData = {
      nome: novoCurso,
      nivel: 1,
      periodo: "Manha",
      area: "Contabilidade",
    }; // Valores padrão

    try {
      const resposta = await fetch("http://localhost:5000/cursos", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(cursoData),
      });

      if (resposta.ok) {
        setNovoCurso("");
        fetchCursos(); // Atualiza a lista após adicionar
      } else {
        console.error("Erro ao adicionar curso");
      }
    } catch (error) {
      console.error("Erro na requisição:", error);
    }
  };

  // Remover curso do backend e atualizar a lista
  const removerCurso = async (id) => {
    try {
      const resposta = await fetch(`http://localhost:5000/cursos/${id}`, {
        method: "DELETE",
      });

      if (resposta.ok) {
        fetchCursos(); // Atualiza a lista após remover
      } else {
        console.error("Erro ao remover curso");
      }
    } catch (error) {
      console.error("Erro na requisição:", error);
    }
  };

  // Navega para a página de adicionar curso
  const navigateToAddCurso = () => {
    navigate("/admaddcurso"); // Redireciona para a página de adicionar curso
  };

  // Navega para a página de editar curso
  const navigateToEditCurso = (id) => {
    navigate(`/admeditcurso/${id}`); // Redireciona para a página de editar curso, passando o id
  };

  return (
    <div className="container mt-4">
      <h1 className="text-primary text-center">EducaWeb</h1>
      <ul className="nav nav-tabs justify-content-center mt-3">
        <li className="nav-item mx-2">
          <Link className="nav-link" to="/admlistcurso">
            Cursos
          </Link>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link" href="#">
            Professores
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link" href="#">
            Alunos
          </a>
        </li>
      </ul>

      {/* Título "Cursos" à esquerda */}
      <div className="d-flex justify-content-between align-items-center mt-3">
        <h3>Cursos</h3>

        {/* Botão Adicionar - Azul Claro */}
        <button
          className="btn btn-info"
          onClick={navigateToAddCurso} // Redireciona para a página de adicionar curso
        >
          Adicionar
        </button>
      </div>

      {/* Campo de filtro */}
      <div className="mt-3">
        <input
          type="text"
          className="form-control"
          placeholder="Filtrar cursos por nome"
          value={filtro}
          onChange={(e) => setFiltro(e.target.value)}
        />
      </div>

      <ul className="list-group mt-3">
        {cursosFiltrados.map((curso) => (
          <li
            key={curso.id}
            className="list-group-item d-flex justify-content-between align-items-center"
          >
            {curso.nome}
            <div>
              <button
                className="btn btn-outline-warning btn-sm"
                onClick={() => navigateToEditCurso(curso.id)} // Redireciona para a página de editar curso
              >
                ✏️ Editar
              </button>
              <button
                className="btn btn-outline-danger btn-sm"
                onClick={() => removerCurso(curso.id)}
              >
                🗑️ Remover
              </button>
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
};

export default AdmListCurso;
